import{_ as t,o as s,c as a,aj as i}from"./chunks/framework.C6uXqnaX.js";const g=JSON.parse('{"title":"Service Worker configuration file","description":"","frontmatter":{"untranslated":true},"headers":[],"relativePath":"ecosystem/service-workers/config.md","filePath":"ecosystem/service-workers/config.md"}'),n={name:"ecosystem/service-workers/config.md"};function o(r,e,l,h,d,c){return s(),a("div",null,e[0]||(e[0]=[i('<h1 id="service-worker-configuration-file" tabindex="-1">Service Worker configuration file <a class="header-anchor" href="#service-worker-configuration-file" aria-label="Permalink to &quot;Service Worker configuration file&quot;">​</a></h1><p>This topic describes the properties of the service worker configuration file.</p><h2 id="modifying-the-configuration" tabindex="-1">Modifying the configuration <a class="header-anchor" href="#modifying-the-configuration" aria-label="Permalink to &quot;Modifying the configuration&quot;">​</a></h2><p>The <code>ngsw-config.json</code> JSON configuration file specifies which files and data URLs the Angular service worker should cache and how it should update the cached files and data. The <a href="/tools/cli">Angular CLI</a> processes this configuration file during <code>ng build</code>.</p><p>All file paths must begin with <code>/</code>, which corresponds to the deployment directory — usually <code>dist/&lt;project-name&gt;</code> in CLI projects.</p><p>Unless otherwise commented, patterns use a <strong>limited*</strong> glob format that internally will be converted into regex:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Glob formats</th><th style="text-align:left;">Details</th></tr></thead><tbody><tr><td style="text-align:left;"><code>**</code></td><td style="text-align:left;">Matches 0 or more path segments</td></tr><tr><td style="text-align:left;"><code>*</code></td><td style="text-align:left;">Matches 0 or more characters excluding <code>/</code></td></tr><tr><td style="text-align:left;"><code>?</code></td><td style="text-align:left;">Matches exactly one character excluding <code>/</code></td></tr><tr><td style="text-align:left;"><code>!</code> prefix</td><td style="text-align:left;">Marks the pattern as being negative, meaning that only files that don&#39;t match the pattern are included</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Special characters need to be escaped</p><p>Pay attention that some characters with a special meaning in a regular expression are not escaped and also the pattern is not wrapped in <code>^</code>/<code>$</code> in the internal glob to regex conversion.</p><p><code>$</code> is a special character in regex that matches the end of the string and will not be automatically escaped when converting the glob pattern to a regular expression.</p><p>If you want to literally match the <code>$</code> character, you have to escape it yourself (with <code>\\\\$</code>). For example, the glob pattern <code>/foo/bar/$value</code> results in an unmatchable expression, because it is impossible to have a string that has any characters after it has ended.</p><p>The pattern will not be automatically wrapped in <code>^</code> and <code>$</code> when converting it to a regular expression. Therefore, the patterns will partially match the request URLs.</p><p>If you want your patterns to match the beginning and/or end of URLs, you can add <code>^</code>/<code>$</code> yourself. For example, the glob pattern <code>/foo/bar/*.js</code> will match both <code>.js</code> and <code>.json</code> files. If you want to only match <code>.js</code> files, use <code>/foo/bar/*.js$</code>.</p></div><p>Example patterns:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Patterns</th><th style="text-align:left;">Details</th></tr></thead><tbody><tr><td style="text-align:left;"><code>/**/*.html</code></td><td style="text-align:left;">Specifies all HTML files</td></tr><tr><td style="text-align:left;"><code>/*.html</code></td><td style="text-align:left;">Specifies only HTML files in the root</td></tr><tr><td style="text-align:left;"><code>!/**/*.map</code></td><td style="text-align:left;">Exclude all sourcemaps</td></tr></tbody></table><h2 id="service-worker-configuration-properties" tabindex="-1">Service worker configuration properties <a class="header-anchor" href="#service-worker-configuration-properties" aria-label="Permalink to &quot;Service worker configuration properties&quot;">​</a></h2><p>The following sections describe each property of the configuration file.</p><h3 id="appdata" tabindex="-1"><code>appData</code> <a class="header-anchor" href="#appdata" aria-label="Permalink to &quot;`appData`&quot;">​</a></h3><p>This section enables you to pass any data you want that describes this particular version of the application. The <code>SwUpdate</code> service includes that data in the update notifications. Many applications use this section to provide additional information for the display of UI popups, notifying users of the available update.</p><h3 id="index" tabindex="-1"><code>index</code> <a class="header-anchor" href="#index" aria-label="Permalink to &quot;`index`&quot;">​</a></h3><p>Specifies the file that serves as the index page to satisfy navigation requests. Usually this is <code>/index.html</code>.</p><h3 id="assetgroups" tabindex="-1"><code>assetGroups</code> <a class="header-anchor" href="#assetgroups" aria-label="Permalink to &quot;`assetGroups`&quot;">​</a></h3><p><em>Assets</em> are resources that are part of the application version that update along with the application. They can include resources loaded from the page&#39;s origin as well as third-party resources loaded from CDNs and other external URLs. As not all such external URLs might be known at build time, URL patterns can be matched.</p><div class="tip custom-block"><p class="custom-block-title">HELPFUL</p><p>For the service worker to handle resources that are loaded from different origins, make sure that <a href="https://developer.mozilla.org/docs/Web/HTTP/CORS" target="_blank" rel="noreferrer">CORS</a> is correctly configured on each origin&#39;s server.</p></div><p>This field contains an array of asset groups, each of which defines a set of asset resources and the policy by which they are cached.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;assetGroups&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      …</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      …</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">HELPFUL</p><p>When the ServiceWorker handles a request, it checks asset groups in the order in which they appear in <code>ngsw-config.json</code>. The first asset group that matches the requested resource handles the request.</p></div><p>It is recommended that you put the more specific asset groups higher in the list. For example, an asset group that matches <code>/foo.js</code> should appear before one that matches <code>*.js</code>.</p><p>Each asset group specifies both a group of resources and a policy that governs them. This policy determines when the resources are fetched and what happens when changes are detected.</p><p>Asset groups follow the TypeScript interface shown here:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">interface</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> AssetGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  name</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  installMode</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;prefetch&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;lazy&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  updateMode</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;prefetch&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;lazy&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  resources</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    files</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[];</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    urls</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[];</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  };</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  cacheQueryOptions</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    ignoreSearch</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> boolean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  };</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Each <code>AssetGroup</code> is defined by the following asset group properties.</p><h4 id="name" tabindex="-1"><code>name</code> <a class="header-anchor" href="#name" aria-label="Permalink to &quot;`name`&quot;">​</a></h4><p>A <code>name</code> is mandatory. It identifies this particular group of assets between versions of the configuration.</p><h4 id="installmode" tabindex="-1"><code>installMode</code> <a class="header-anchor" href="#installmode" aria-label="Permalink to &quot;`installMode`&quot;">​</a></h4><p>The <code>installMode</code> determines how these resources are initially cached. The <code>installMode</code> can be either of two values:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Values</th><th style="text-align:left;">Details</th></tr></thead><tbody><tr><td style="text-align:left;"><code>prefetch</code></td><td style="text-align:left;">Tells the Angular service worker to fetch every single listed resource while it&#39;s caching the current version of the application. This is bandwidth-intensive but ensures resources are available whenever they&#39;re requested, even if the browser is currently offline.</td></tr><tr><td style="text-align:left;"><code>lazy</code></td><td style="text-align:left;">Does not cache any of the resources up front. Instead, the Angular service worker only caches resources for which it receives requests. This is an on-demand caching mode. Resources that are never requested are not cached. This is useful for things like images at different resolutions, so the service worker only caches the correct assets for the particular screen and orientation.</td></tr></tbody></table><p>Defaults to <code>prefetch</code>.</p><h4 id="updatemode" tabindex="-1"><code>updateMode</code> <a class="header-anchor" href="#updatemode" aria-label="Permalink to &quot;`updateMode`&quot;">​</a></h4><p>For resources already in the cache, the <code>updateMode</code> determines the caching behavior when a new version of the application is discovered. Any resources in the group that have changed since the previous version are updated in accordance with <code>updateMode</code>.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Values</th><th style="text-align:left;">Details</th></tr></thead><tbody><tr><td style="text-align:left;"><code>prefetch</code></td><td style="text-align:left;">Tells the service worker to download and cache the changed resources immediately.</td></tr><tr><td style="text-align:left;"><code>lazy</code></td><td style="text-align:left;">Tells the service worker to not cache those resources. Instead, it treats them as unrequested and waits until they&#39;re requested again before updating them. An <code>updateMode</code> of <code>lazy</code> is only valid if the <code>installMode</code> is also <code>lazy</code>.</td></tr></tbody></table><p>Defaults to the value <code>installMode</code> is set to.</p><h4 id="resources" tabindex="-1"><code>resources</code> <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;`resources`&quot;">​</a></h4><p>This section describes the resources to cache, broken up into the following groups:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Resource groups</th><th style="text-align:left;">Details</th></tr></thead><tbody><tr><td style="text-align:left;"><code>files</code></td><td style="text-align:left;">Lists patterns that match files in the distribution directory. These can be single files or glob-like patterns that match a number of files.</td></tr><tr><td style="text-align:left;"><code>urls</code></td><td style="text-align:left;">Includes both URLs and URL patterns that are matched at runtime. These resources are not fetched directly and do not have content hashes, but they are cached according to their HTTP headers. This is most useful for CDNs such as the Google Fonts service. <br> <em>(Negative glob patterns are not supported and <code>?</code> will be matched literally; that is, it will not match any character other than <code>?</code>.)</em></td></tr></tbody></table><h4 id="cachequeryoptions" tabindex="-1"><code>cacheQueryOptions</code> <a class="header-anchor" href="#cachequeryoptions" aria-label="Permalink to &quot;`cacheQueryOptions`&quot;">​</a></h4><p>These options are used to modify the matching behavior of requests. They are passed to the browsers <code>Cache#match</code> function. See <a href="https://developer.mozilla.org/docs/Web/API/Cache/match" target="_blank" rel="noreferrer">MDN</a> for details. Currently, only the following options are supported:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Options</th><th style="text-align:left;">Details</th></tr></thead><tbody><tr><td style="text-align:left;"><code>ignoreSearch</code></td><td style="text-align:left;">Ignore query parameters. Defaults to <code>false</code>.</td></tr></tbody></table><h3 id="datagroups" tabindex="-1"><code>dataGroups</code> <a class="header-anchor" href="#datagroups" aria-label="Permalink to &quot;`dataGroups`&quot;">​</a></h3><p>Unlike asset resources, data requests are not versioned along with the application. They&#39;re cached according to manually-configured policies that are more useful for situations such as API requests and other data dependencies.</p><p>This field contains an array of data groups, each of which defines a set of data resources and the policy by which they are cached.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;dataGroups&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    {</span></span>\n<span class="line"><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">      …</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    {</span></span>\n<span class="line"><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">      …</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">HELPFUL</p><p>When the ServiceWorker handles a request, it checks data groups in the order in which they appear in <code>ngsw-config.json</code>. The first data group that matches the requested resource handles the request.</p></div><p>It is recommended that you put the more specific data groups higher in the list. For example, a data group that matches <code>/api/foo.json</code> should appear before one that matches <code>/api/*.json</code>.</p><p>Data groups follow this TypeScript interface:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> interface</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> DataGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  name</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  urls</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[];</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  version</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> number</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  cacheConfig</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    maxSize</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> number</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    maxAge</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    timeout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    refreshAhead</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    strategy</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;freshness&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;performance&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  };</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  cacheQueryOptions</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    ignoreSearch</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> boolean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  };</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Each <code>DataGroup</code> is defined by the following data group properties.</p><h4 id="datagroups-name" tabindex="-1"><code>name</code> <a class="header-anchor" href="#datagroups-name" aria-label="Permalink to &quot;`name` {#datagroups-name}&quot;">​</a></h4><p>Similar to <code>assetGroups</code>, every data group has a <code>name</code> which uniquely identifies it.</p><h4 id="urls" tabindex="-1"><code>urls</code> <a class="header-anchor" href="#urls" aria-label="Permalink to &quot;`urls`&quot;">​</a></h4><p>A list of URL patterns. URLs that match these patterns are cached according to this data group&#39;s policy. Only non-mutating requests (GET and HEAD) are cached.</p><ul><li>Negative glob patterns are not supported</li><li><code>?</code> is matched literally; that is, it matches <em>only</em> the character <code>?</code></li></ul><h4 id="version" tabindex="-1"><code>version</code> <a class="header-anchor" href="#version" aria-label="Permalink to &quot;`version`&quot;">​</a></h4><p>Occasionally APIs change formats in a way that is not backward-compatible. A new version of the application might not be compatible with the old API format and thus might not be compatible with existing cached resources from that API.</p><p><code>version</code> provides a mechanism to indicate that the resources being cached have been updated in a backwards-incompatible way, and that the old cache entries —those from previous versions— should be discarded.</p><p><code>version</code> is an integer field and defaults to <code>1</code>.</p><h4 id="cacheconfig" tabindex="-1"><code>cacheConfig</code> <a class="header-anchor" href="#cacheconfig" aria-label="Permalink to &quot;`cacheConfig`&quot;">​</a></h4><p>The following properties define the policy by which matching requests are cached.</p><h5 id="maxsize" tabindex="-1"><code>maxSize</code> <a class="header-anchor" href="#maxsize" aria-label="Permalink to &quot;`maxSize`&quot;">​</a></h5><p>The maximum number of entries, or responses, in the cache.</p><div class="danger custom-block"><p class="custom-block-title">CRITICAL</p><p>Open-ended caches can grow in unbounded ways and eventually exceed storage quotas, resulting in eviction.</p></div><h5 id="maxage" tabindex="-1"><code>maxAge</code> <a class="header-anchor" href="#maxage" aria-label="Permalink to &quot;`maxAge`&quot;">​</a></h5><p>The <code>maxAge</code> parameter indicates how long responses are allowed to remain in the cache before being considered invalid and evicted. <code>maxAge</code> is a duration string, using the following unit suffixes:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Suffixes</th><th style="text-align:left;">Details</th></tr></thead><tbody><tr><td style="text-align:left;"><code>d</code></td><td style="text-align:left;">Days</td></tr><tr><td style="text-align:left;"><code>h</code></td><td style="text-align:left;">Hours</td></tr><tr><td style="text-align:left;"><code>m</code></td><td style="text-align:left;">Minutes</td></tr><tr><td style="text-align:left;"><code>s</code></td><td style="text-align:left;">Seconds</td></tr><tr><td style="text-align:left;"><code>u</code></td><td style="text-align:left;">Milliseconds</td></tr></tbody></table><p>For example, the string <code>3d12h</code> caches content for up to three and a half days.</p><h5 id="timeout" tabindex="-1"><code>timeout</code> <a class="header-anchor" href="#timeout" aria-label="Permalink to &quot;`timeout`&quot;">​</a></h5><p>This duration string specifies the network timeout. The network timeout is how long the Angular service worker waits for the network to respond before using a cached response, if configured to do so. <code>timeout</code> is a duration string, using the following unit suffixes:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Suffixes</th><th style="text-align:left;">Details</th></tr></thead><tbody><tr><td style="text-align:left;"><code>d</code></td><td style="text-align:left;">Days</td></tr><tr><td style="text-align:left;"><code>h</code></td><td style="text-align:left;">Hours</td></tr><tr><td style="text-align:left;"><code>m</code></td><td style="text-align:left;">Minutes</td></tr><tr><td style="text-align:left;"><code>s</code></td><td style="text-align:left;">Seconds</td></tr><tr><td style="text-align:left;"><code>u</code></td><td style="text-align:left;">Milliseconds</td></tr></tbody></table><p>For example, the string <code>5s30u</code> translates to five seconds and 30 milliseconds of network timeout.</p><h5 id="refreshahead" tabindex="-1"><code>refreshAhead</code> <a class="header-anchor" href="#refreshahead" aria-label="Permalink to &quot;`refreshAhead`&quot;">​</a></h5><p>This duration string specifies the time ahead of the expiration of a cached resource when the Angular service worker should proactively attempt to refresh the resource from the network. The <code>refreshAhead</code> duration is an optional configuration that determines how much time before the expiration of a cached response the service worker should initiate a request to refresh the resource from the network.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Suffixes</th><th style="text-align:left;">Details</th></tr></thead><tbody><tr><td style="text-align:left;"><code>d</code></td><td style="text-align:left;">Days</td></tr><tr><td style="text-align:left;"><code>h</code></td><td style="text-align:left;">Hours</td></tr><tr><td style="text-align:left;"><code>m</code></td><td style="text-align:left;">Minutes</td></tr><tr><td style="text-align:left;"><code>s</code></td><td style="text-align:left;">Seconds</td></tr><tr><td style="text-align:left;"><code>u</code></td><td style="text-align:left;">Milliseconds</td></tr></tbody></table><p>For example, the string <code>1h30m</code> translates to one hour and 30 minutes ahead of the expiration time.</p><h5 id="strategy" tabindex="-1"><code>strategy</code> <a class="header-anchor" href="#strategy" aria-label="Permalink to &quot;`strategy`&quot;">​</a></h5><p>The Angular service worker can use either of two caching strategies for data resources.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Caching strategies</th><th style="text-align:left;">Details</th></tr></thead><tbody><tr><td style="text-align:left;"><code>performance</code></td><td style="text-align:left;">The default, optimizes for responses that are as fast as possible. If a resource exists in the cache, the cached version is used, and no network request is made. This allows for some staleness, depending on the <code>maxAge</code>, in exchange for better performance. This is suitable for resources that don&#39;t change often; for example, user avatar images.</td></tr><tr><td style="text-align:left;"><code>freshness</code></td><td style="text-align:left;">Optimizes for currency of data, preferentially fetching requested data from the network. Only if the network times out, according to <code>timeout</code>, does the request fall back to the cache. This is useful for resources that change frequently; for example, account balances.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">HELPFUL</p><p>You can also emulate a third strategy, <a href="https://developers.google.com/web/fundamentals/instant-and-offline/offline-cookbook/#stale-while-revalidate" target="_blank" rel="noreferrer">staleWhileRevalidate</a>, which returns cached data if it is available, but also fetches fresh data from the network in the background for next time. To use this strategy set <code>strategy</code> to <code>freshness</code> and <code>timeout</code> to <code>0u</code> in <code>cacheConfig</code>.</p></div><p>This essentially does the following:</p><ol><li>Try to fetch from the network first.</li><li>If the network request does not complete immediately, that is after a timeout of 0 ms, ignore the cache age and fall back to the cached value.</li><li>Once the network request completes, update the cache for future requests.</li><li>If the resource does not exist in the cache, wait for the network request anyway.</li></ol><h5 id="cacheopaqueresponses" tabindex="-1"><code>cacheOpaqueResponses</code> <a class="header-anchor" href="#cacheopaqueresponses" aria-label="Permalink to &quot;`cacheOpaqueResponses`&quot;">​</a></h5><p>Whether the Angular service worker should cache opaque responses or not.</p><p>If not specified, the default value depends on the data group&#39;s configured strategy:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Strategies</th><th style="text-align:left;">Details</th></tr></thead><tbody><tr><td style="text-align:left;">Groups with the <code>freshness</code> strategy</td><td style="text-align:left;">The default value is <code>true</code> and the service worker caches opaque responses. These groups will request the data every time and only fall back to the cached response when offline or on a slow network. Therefore, it doesn&#39;t matter if the service worker caches an error response.</td></tr><tr><td style="text-align:left;">Groups with the <code>performance</code> strategy</td><td style="text-align:left;">The default value is <code>false</code> and the service worker doesn&#39;t cache opaque responses. These groups would continue to return a cached response until <code>maxAge</code> expires, even if the error was due to a temporary network or server issue. Therefore, it would be problematic for the service worker to cache an error response.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Comment on opaque responses</p><p>In case you are not familiar, an <a href="https://fetch.spec.whatwg.org#concept-filtered-response-opaque" target="_blank" rel="noreferrer">opaque response</a> is a special type of response returned when requesting a resource that is on a different origin which doesn&#39;t return CORS headers. One of the characteristics of an opaque response is that the service worker is not allowed to read its status, meaning it can&#39;t check if the request was successful or not. See <a href="https://developers.google.com/web/updates/2015/03/introduction-to-fetch#response_types" target="_blank" rel="noreferrer">Introduction to <code>fetch()</code></a> for more details.</p><p>If you are not able to implement CORS — for example, if you don&#39;t control the origin — prefer using the <code>freshness</code> strategy for resources that result in opaque responses.</p></div><h4 id="datagroups-cachequeryoptions" tabindex="-1"><code>cacheQueryOptions</code> <a class="header-anchor" href="#datagroups-cachequeryoptions" aria-label="Permalink to &quot;`cacheQueryOptions` {#datagroups-cachequeryoptions}&quot;">​</a></h4><p>See <a href="#assetgroups">assetGroups</a> for details.</p><h3 id="navigationurls" tabindex="-1"><code>navigationUrls</code> <a class="header-anchor" href="#navigationurls" aria-label="Permalink to &quot;`navigationUrls`&quot;">​</a></h3><p>This optional section enables you to specify a custom list of URLs that will be redirected to the index file.</p><h4 id="handling-navigation-requests" tabindex="-1">Handling navigation requests <a class="header-anchor" href="#handling-navigation-requests" aria-label="Permalink to &quot;Handling navigation requests&quot;">​</a></h4><p>The ServiceWorker redirects navigation requests that don&#39;t match any <code>asset</code> or <code>data</code> group to the specified <a href="#index">index file</a>. A request is considered to be a navigation request if:</p><ul><li>Its <a href="https://developer.mozilla.org/docs/Web/API/Request/method" target="_blank" rel="noreferrer">method</a> is <code>GET</code></li><li>Its <a href="https://developer.mozilla.org/docs/Web/API/Request/mode" target="_blank" rel="noreferrer">mode</a> is <code>navigate</code></li><li>It accepts a <code>text/html</code> response as determined by the value of the <code>Accept</code> header</li><li>Its URL matches the following criteria: <ul><li>The URL must not contain a file extension (that is, a <code>.</code>) in the last path segment</li><li>The URL must not contain <code>__</code></li></ul></li></ul><div class="tip custom-block"><p class="custom-block-title">HELPFUL</p><p>To configure whether navigation requests are sent through to the network or not, see the <a href="#navigationrequeststrategy">navigationRequestStrategy</a> section and <a href="#applicationmaxage">applicationMaxAge</a> sections.</p></div><h4 id="matching-navigation-request-urls" tabindex="-1">Matching navigation request URLs <a class="header-anchor" href="#matching-navigation-request-urls" aria-label="Permalink to &quot;Matching navigation request URLs&quot;">​</a></h4><p>While these default criteria are fine in most cases, it is sometimes desirable to configure different rules. For example, you might want to ignore specific routes, such as those that are not part of the Angular app, and pass them through to the server.</p><p>This field contains an array of URLs and <a href="#modifying-the-configuration">glob-like</a> URL patterns that are matched at runtime. It can contain both negative patterns (that is, patterns starting with <code>!</code>) and non-negative patterns and URLs.</p><p>Only requests whose URLs match <em>any</em> of the non-negative URLs/patterns and <em>none</em> of the negative ones are considered navigation requests. The URL query is ignored when matching.</p><p>If the field is omitted, it defaults to:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;/**&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Include all URLs.</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;!/**/*.*&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Exclude URLs to files (containing a file extension in the last segment).</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;!/**/*__*&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Exclude URLs containing `__` in the last segment.</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;!/**/*__*/**&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Exclude URLs containing `__` in any other segment.</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span></code></pre></div><h3 id="navigationrequeststrategy" tabindex="-1"><code>navigationRequestStrategy</code> <a class="header-anchor" href="#navigationrequeststrategy" aria-label="Permalink to &quot;`navigationRequestStrategy`&quot;">​</a></h3><p>This optional property enables you to configure how the service worker handles navigation requests:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;navigationRequestStrategy&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;freshness&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><table tabindex="0"><thead><tr><th style="text-align:left;">Possible values</th><th style="text-align:left;">Details</th></tr></thead><tbody><tr><td style="text-align:left;"><code>&#39;performance&#39;</code></td><td style="text-align:left;">The default setting. Serves the specified <a href="#index">index file</a>, which is typically cached.</td></tr><tr><td style="text-align:left;"><code>&#39;freshness&#39;</code></td><td style="text-align:left;">Passes the requests through to the network and falls back to the <code>performance</code> behavior when offline. This value is useful when the server redirects the navigation requests elsewhere using a <code>3xx</code> HTTP redirect status code. Reasons for using this value include: <ul><li> Redirecting to an authentication website when authentication is not handled by the application </li> <li> Redirecting specific URLs to avoid breaking existing links/bookmarks after a website redesign </li> <li> Redirecting to a different website, such as a server-status page, while a page is temporarily down </li></ul></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">IMPORTANT</p><p>The <code>freshness</code> strategy usually results in more requests sent to the server, which can increase response latency. It is recommended that you use the default performance strategy whenever possible.</p></div><h3 id="applicationmaxage" tabindex="-1"><code>applicationMaxAge</code> <a class="header-anchor" href="#applicationmaxage" aria-label="Permalink to &quot;`applicationMaxAge`&quot;">​</a></h3><p>This optional property enables you to configure how long the service worker serves an application version from its cache. The age is measured from the time you built the application, not from the time the files were cached on the device.</p><p>Within the <code>applicationMaxAge</code>, the service worker serves files from the cache. Beyond it, the service worker sends all requests to the network, including asset and data requests, even if no newer version exists. The application does not work offline until a new build is deployed and the device has fetched it.</p><p>If you omit <code>applicationMaxAge</code>, there is no maximum age and the service worker serves cached versions regardless of how old they are.</p>',112)]))}const u=t(n,[["render",o]]);export{g as __pageData,u as default};
